export function totalOpportunityAmount(
  opportunities: readonly OpportunityRecord[],
): number {
  const total = opportunities.reduce(
    (sum, opportunity) => sum + opportunity.amount,
    0,
  );
  return Math.round(total * 100) / 100;
}

